pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address userA = address(0x1234);
        address userB = address(0x5678);

        vm.deal(userA, 1 ether);
        vm.prank(userA);
        c.deposit{value: 1}();

        // After A's deposit, in reference A's balance = 1, in bug A's balance = 0.
        // Now A calls refund: reference will transfer 1 wei to A, bug transfers 0.
        vm.prank(userA);
        c.refund();

        // After refund, contract balance differs:
        // Reference: A's balance was 1, contract had 1, after refund contract balance = 0.
        // Bug: A's balance was 0, contract had 1, after refund contract balance = 1.
        assertTrue(address(c).balance == 0);
    }
}

