        address user = address(0x2);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.deposit{value: 1 ether}();
        // migrateTo by creator; reference sends to address(this) which rejects => revert; bug sends to msg.sender (creator, an EOA) => success
