        address creator = address(0x1);
        address user = address(0x2);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.deposit{value: 1 ether}();
        // to = address(this) which has no receive, reference reverts, bug sends to msg.sender (creator)
        bool ok;
        vm.prank(creator);
        try c.migrateTo(address(this)) { ok = true; } catch { ok = false; }
        // Reference: revert, so ok = false and balance = 1 ether
        // Bug: success, so ok = true and balance = 0
        assertTrue(ok == false && address(c).balance == 1 ether);
    }
}

