pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address creator = address(0x1);
        address depositor = address(0x2);
        // Set creator as msg.sender when deploying
        vm.prank(creator);
        c = new C();
        // Depositor sends 1 ether
        vm.deal(depositor, 1 ether);
        vm.prank(depositor);
        c.deposit{value: 1 ether}();
        // Creator calls migrateTo to address(this) which has no receive, so reference reverts, buggy sends to msg.sender
        vm.prank(creator);
        try c.migrateTo(address(this)) {
            // Bug: succeeds, so contract balance should be 0
            assertTrue(address(c).balance == 0 ether);
        } catch {
            // Reference: reverts, so contract balance should be 1 ether
            assertTrue(address(c).balance == 1 ether);
        }
    }
}

